   contextWindow?: number;
   maxTokens?: number;
   reasoning?: boolean;
   api?: string;
+  /** 官方思考等级映射（如 deepseek-v4 仅 high/max；kimi-k3 无 xhigh） */
+  thinkingLevelMap?: Record<string, string | null>;
