+          }
+          if (Object.keys(tlm).length > 0) out.thinkingLevelMap = tlm;
+        }
+        if (typeof entry.compat === "object" && entry.compat !== null) {
+          out.compat = entry.compat as Record<string, unknown>;
+        }
         _piCatalog.map.set(id, out);
       }
     }
   } catch {
     // 无缓存或不可读：规则兜底
   }
   return _piCatalog.map;
 }

